// Dark launch and native appearance for the generated iOS project.
//
// ios/ is regenerated by `cap add ios` on every CI run, so these settings
// cannot be committed there; cap:sync runs this script after the sync.
// Without it, Capacitor's template launch screen shows its white default
// splash on systemBackgroundColor (white in light mode) before the dark
// SApay web UI loads, and the status bar text is dark on a dark page.
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';

// Must match ios.backgroundColor in capacitor.config.ts.
const BACKGROUND = { hex: '#0A0A0A', component: (0x0a / 255).toFixed(4) };

const storyboardPath = path.resolve('ios/App/App/Base.lproj/LaunchScreen.storyboard');
const plistPath = path.resolve('ios/App/App/Info.plist');

async function readOrExit(file) {
  try {
    return await readFile(file, 'utf8');
  } catch {
    console.error(`${file} not found. Run npx cap add ios before npm run cap:sync.`);
    process.exit(1);
  }
}

let storyboard = await readOrExit(storyboardPath);
const solidColor = `<color key="backgroundColor" red="${BACKGROUND.component}" green="${BACKGROUND.component}" blue="${BACKGROUND.component}" alpha="1" colorSpace="custom" customColorSpace="sRGB"/>`;
storyboard = storyboard
  // Drop the template's white splash image; the launch screen is a plain dark view.
  .replace(/ image="Splash"/g, '')
  .replace(/<color key="backgroundColor" systemColor="systemBackgroundColor"\/>/g, solidColor);
if (!storyboard.includes(solidColor) || storyboard.includes('image="Splash"')) {
  throw new Error('LaunchScreen.storyboard has an unexpected layout; dark launch screen not applied.');
}
await writeFile(storyboardPath, storyboard, 'utf8');

let plist = await readOrExit(plistPath);
const darkStyle = '<key>UIUserInterfaceStyle</key>';
if (!plist.includes(darkStyle)) {
  const closingIndex = plist.lastIndexOf('</dict>');
  if (closingIndex < 0) throw new Error('Info.plist is missing its root dict element.');
  // SApay has a dark-only identity: force dark appearance so system colours,
  // the status bar and keyboards match it regardless of the device setting.
  plist = `${plist.slice(0, closingIndex)}  ${darkStyle}\n  <string>Dark</string>\n${plist.slice(closingIndex)}`;
  await writeFile(plistPath, plist, 'utf8');
}
console.log(`Configured dark iOS launch screen (${BACKGROUND.hex}) and UIUserInterfaceStyle=Dark.`);
